function drawAttractPoint(x, y) {
    push();
    // Pulsing center only - no circle
    let pulse = sin(frameCount * 0.05) * 0.3 + 0.7;
    noStroke();
    fill(100, 150, 255, 50 * pulse);
    ellipse(x, y, 20 * pulse);
    fill(150, 200, 255, 150 * pulse);
    ellipse(x, y, 8 * pulse);
    pop();
}

// ========== CONSTELLATION STAR CURSOR ==========
function drawConstellationCursor(x, y) {
    let starSize = 18;
    let glowRadius = 35;

    // === GLOW EFFECT ===
    for (let i = 5; i > 0; i--) {
        let alpha = map(i, 0, 5, 5, 60);
        let radius = map(i, 0, 5, glowRadius, 10);
        noStroke();
        fill(150, 180, 255, alpha);
        ellipse(x, y, radius * 2);
    }

    // === MAIN STAR ===
    noStroke();
    fill(255, 240, 220, 220);
    ellipse(x, y, starSize * 0.5);

    // === STAR SPIKES ===
    strokeWeight(2);
    stroke(255, 255, 255, 200);
    line(x - starSize * 1.2, y, x - starSize * 0.3, y);
    line(x + starSize * 0.3, y, x + starSize * 1.2, y);
    line(x, y - starSize * 1.2, x, y - starSize * 0.3);
    line(x, y + starSize * 0.3, x, y + starSize * 1.2);
    line(x - starSize * 0.8, y - starSize * 0.8, x - starSize * 0.2, y - starSize * 0.2);
    line(x + starSize * 0.2, y + starSize * 0.2, x + starSize * 0.8, y + starSize * 0.8);
    line(x + starSize * 0.8, y - starSize * 0.8, x + starSize * 0.2, y - starSize * 0.2);
    line(x - starSize * 0.2, y + starSize * 0.2, x - starSize * 0.8, y + starSize * 0.8);

    // === CONSTELLATION ORBITS ===
    let time = millis() / 3000;
    let numOrbits = 6;

    for (let i = 0; i < numOrbits; i++) {
        let angle = (TWO_PI / numOrbits) * i + time;
        let orbitRadius = 25 + sin(time * 2 + i) * 8;
        let orbitX = x + cos(angle) * orbitRadius;
        let orbitY = y + sin(angle) * orbitRadius;

        // Orbit star dots
        let brightness = map(sin(time * 3 + i * 2), -1, 1, 80, 255);
        noStroke();
        fill(200, 220, 255, brightness * 0.5);
        ellipse(orbitX, orbitY, 4);

        // Connecting lines from center
        stroke(150, 180, 255, 40 + brightness * 0.1);
        strokeWeight(0.8);
        line(x, y, orbitX, orbitY);

        // Connect nearby orbit dots
        let nextIndex = (i + 1) % numOrbits;
        let nextAngle = (TWO_PI / numOrbits) * nextIndex + time;
        let nextOrbitRadius = 25 + sin(time * 2 + nextIndex) * 8;
        let nextOrbitX = x + cos(nextAngle) * nextOrbitRadius;
        let nextOrbitY = y + sin(nextAngle) * nextOrbitRadius;

        stroke(200, 220, 255, 30);
        strokeWeight(0.5);
        line(orbitX, orbitY, nextOrbitX, nextOrbitY);
    }

    // === SPARKLING CORE ===
    for (let i = 0; i < 8; i++) {
        var angle = random(TWO_PI);
        let dist = random(3, 12);
        let sparkleX = x + cos(angle) * dist;
        let sparkleY = y + sin(angle) * dist;
        var alpha = random(100, 255);
        noStroke();
        fill(255, 255, 255, alpha);
        ellipse(sparkleX, sparkleY, random(1, 2.5));
    }
}

// ========== PARTICLE CLASS ==========
class Particle {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.size = random(2, 6);
        this.currentSize = this.size;
        this.lifeSpan = 255;
        this.xSpeed = random(-2, 2);
        this.ySpeed = random(-2, 2);
        this.color = color(225, 225, 225);
        this.orbitAngle = random(TWO_PI);
        this.orbitSpeed = random(0.01, 0.05);
        this.isOrbiting = false;
        this.assignedPoint = null;
        this.orbitRadius = random(10, sphereRadius);
        this.theta = random(TWO_PI);
        this.phi = acos(1 - 2 * random(1));
    }

    update() {
        if (isAttracting && attractPoints.length > 0) {
            // If particle doesn't have an assigned point, get one
            if (this.assignedPoint === null) {
                var randomIndex = floor(random(attractPoints.length));
                this.assignedPoint = attractPoints[randomIndex];
            }

            // Check if assigned point still exists
            let pointExists = false;
            for (let point of attractPoints) {
                if (point === this.assignedPoint) {
                    pointExists = true;
                    break;
                }
            }

            if (!pointExists) {
                // Reassign to a new point
                var randomIndex = floor(random(attractPoints.length));
                this.assignedPoint = attractPoints[randomIndex];
                this.orbitAngle = random(TWO_PI);
            }

            let dx = this.assignedPoint.x - this.x;
            let dy = this.assignedPoint.y - this.y;
            let d = dist(this.x, this.y, this.assignedPoint.x, this.assignedPoint.y);

            if (d < sphereRadius) {
                // Orbit within sphere
                this.orbitAngle += this.orbitSpeed;

                // Orbit in a circle around the attract point
                var orbitX = this.assignedPoint.x + this.orbitRadius * cos(this.orbitAngle);
                var orbitY = this.assignedPoint.y + this.orbitRadius * sin(this.orbitAngle);

                // Smoothly move toward orbit position
                this.x += (orbitX - this.x) * 0.05;
                this.y += (orbitY - this.y) * 0.05;

                // Slight vertical oscillation for 3D feel
                this.y += sin(this.orbitAngle * 2) * 0.1;

                this.currentSize = map(this.orbitRadius, 0, sphereRadius, this.size * 1.5, this.size * 0.5);
                this.color = color(100, 150, 255, 255);
                this.isOrbiting = true;
            } else {
                // Move toward attract point
                var angle = atan2(dy, dx);
                let speed = 5;
                this.x += cos(angle) * speed;
                this.y += sin(angle) * speed;
                this.currentSize = this.size;
                this.color = color(225, 225, 225);
                this.isOrbiting = false;
            }
        } else {
            // Normal movement with slight drift
            this.x += this.xSpeed;
            this.y += this.ySpeed;
            this.xSpeed *= 0.99;
            this.ySpeed *= 0.99;
            this.currentSize = this.size;
            this.color = color(225, 225, 225, this.lifeSpan);
            this.isOrbiting = false;
            this.assignedPoint = null;
        }

        // Fade out
        this.lifeSpan -= 0.5;
        if (this.lifeSpan < 50) {
            this.currentSize *= 0.98;
        }

        // Keep particles in bounds
        if (this.x > width) this.x = 0;
        if (this.x < 0) this.x = width;
        if (this.y > height) this.y = 0;
        if (this.y < 0) this.y = height;
    }

    display() {
        push();
        noStroke();

        // Glow effect for orbiting particles
        if (this.isOrbiting) {
            for (let i = 3; i > 0; i--) {
                var alpha = map(i, 0, 3, 10, 50);
                fill(red(this.color), green(this.color), blue(this.color), alpha);
                ellipse(this.x, this.y, this.currentSize * (i * 0.5 + 1));
            }
        }

        fill(this.color);
        ellipse(this.x, this.y, this.currentSize);
        pop();
    }
}

